import { useIntl } from 'react-intl';

import { BasicContainer, Skeleton } from 'components';

interface OverviewProps {
  dataTestId?: string;
}

export const Overview: React.FC<OverviewProps> = ({ dataTestId }) => {
  const { formatMessage } = useIntl();

  const containerDataTestId = dataTestId
    ? `${dataTestId}-container`
    : 'innovation-hub-overview-container';
  const skeletonDataTestId = dataTestId
    ? `${dataTestId}-skeleton`
    : 'innovation-hub-overview-skeleton';

  return (
    <BasicContainer
      dataTestId={containerDataTestId}
      header={{
        title: formatMessage({
          id: 'Innovation.InnovationHub.Overview.GlobalTotalInnovationPerformance.title',
        }),
      }}
    >
      <Skeleton
        dataTestId={skeletonDataTestId}
        height="120px"
        length={1}
        width="100%"
      />
    </BasicContainer>
  );
};
